import { createContext, useContext, useMemo } from 'react'

interface PermissionsContextValue {
  canDo: (key: string) => boolean
  permissions: ReadonlySet<string>
}

const PermissionsContext = createContext<PermissionsContextValue>({
  canDo: () => false,
  permissions: new Set(),
})

interface PermissionsProviderProps {
  /** Serialized as JSON array from the server component */
  permissionKeys: string[]
  children: React.ReactNode
}

export function PermissionsProvider({ permissionKeys, children }: PermissionsProviderProps) {
  const permissions = useMemo(() => new Set(permissionKeys), [permissionKeys])

  const value = useMemo<PermissionsContextValue>(
    () => ({
      canDo: (key: string) => permissions.has(key),
      permissions,
    }),
    [permissions],
  )

  return <PermissionsContext.Provider value={value}>{children}</PermissionsContext.Provider>
}

export function usePermissions() {
  return useContext(PermissionsContext)
}
