/**
 * Pure commission calculation function — no side effects, no imports.
 * Used in CommissionPreview, RuleEditorDrawer, and NewBookingDrawer.
 *
 * All amounts are in cents.
 */

export interface CommissionPreviewRule {
  percentage: number | null
  flat_fee_cents: number | null
  tip_split_pct: number
}

export interface CommissionPreviewResult {
  commission: number
  tipCommission: number
  total: number
  breakdown: string
}

/**
 * Calculate artist commission from service price, tip, and rule.
 * Mirrors the trigger logic in `on_booking_completed_commission`.
 */
export function calculateCommission(
  price: number,
  tip: number,
  rule: CommissionPreviewRule,
): CommissionPreviewResult {
  let commission = 0
  const parts: string[] = []

  if (rule.percentage != null && rule.flat_fee_cents != null) {
    commission =
      Math.round((price * rule.percentage) / 100) + rule.flat_fee_cents
    parts.push(`${rule.percentage}% + flat fee`)
  } else if (rule.percentage != null) {
    commission = Math.round((price * rule.percentage) / 100)
    parts.push(`${rule.percentage}%`)
  } else if (rule.flat_fee_cents != null) {
    commission = rule.flat_fee_cents
    parts.push(`flat fee`)
  }

  const tipCommission = Math.round((tip * rule.tip_split_pct) / 100)
  if (tip > 0 && rule.tip_split_pct > 0) {
    parts.push(`${rule.tip_split_pct}% tip`)
  }

  return {
    commission,
    tipCommission,
    total: commission + tipCommission,
    breakdown: parts.join(' + '),
  }
}

import type { NextRequest } from 'next/server'
import { z } from 'zod'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { requireFeature, hasFeature } from '@/lib/billing/feature-gate'
import { logger } from '@/lib/logger'

const ListRecordsSchema = z.object({
  artist_id: z.string().uuid().optional(),
  status: z
    .enum(['pending', 'approved', 'paid', 'cancelled', 'disputed'])
    .optional(),
  from: z.string().date().optional(),
  to: z.string().date().optional(),
  q: z.string().max(200).optional(),
  page: z.coerce.number().int().min(1).default(1),
  per_page: z.coerce.number().int().min(1).max(100).default(50),
})

export async function GET(request: NextRequest) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return Response.json({ error: 'Unauthorized' }, { status: 401 })

  const ip = request.headers.get('x-forwarded-for') ?? authUser.user.authId
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return Response.json({ error: 'Too many requests' }, { status: 429 })

  // Feature gate — Studio tier+
  const supabase = await createClient()
  const subResult = await supabase
    .from('subscriptions')
    .select('plan_tier')
    .eq('studio_id', authUser.studioId)
    .eq('status', 'active')
    .maybeSingle()
  const plan = (subResult.data?.plan_tier ?? 'solo') as Parameters<typeof hasFeature>[0]
  const gateResp = requireFeature(plan, 'commissions')
  if (gateResp) return gateResp

  const raw = Object.fromEntries(request.nextUrl.searchParams)
  const parsed = ListRecordsSchema.safeParse(raw)
  if (!parsed.success)
    return Response.json({ error: parsed.error.flatten() }, { status: 400 })

  const { artist_id, status, from, to, q, page, per_page } = parsed.data
  const isAdminOrOwner = ['owner', 'admin'].includes(authUser.role)

  let query = supabase
    .from('commission_records')
    .select(
      `id, booking_id, artist_id, service_id, rule_id, rule_snapshot,
       service_price_cents, tip_cents, commission_cents, tip_commission_cents,
       total_cents, calculation_notes, status,
       approved_by, approved_at, cancelled_at, cancelled_by, cancellation_reason,
       dispute_reason, disputed_by, created_at, updated_at,
       artists!commission_records_artist_id_fkey(id, display_name, avatar_url),
       services!commission_records_service_id_fkey(id, name),
       bookings!commission_records_booking_id_fkey(id, scheduled_at, client_id,
         clients!bookings_client_id_fkey(id, first_name, last_name))`,
      { count: 'exact' },
    )
    .eq('studio_id', authUser.studioId)
    .order('created_at', { ascending: false })
    .range((page - 1) * per_page, page * per_page - 1)

  if (status) query = query.eq('status', status)
  if (from) query = query.gte('created_at', from)
  if (to) query = query.lte('created_at', to + 'T23:59:59Z')

  // Artists only see their own records (RLS enforces, UI mirrors)
  if (!isAdminOrOwner) {
    // RLS already scopes; artist_id filter is UX-layer defense
    if (artist_id) query = query.eq('artist_id', artist_id)
  } else if (artist_id) {
    query = query.eq('artist_id', artist_id)
  }

  const { data, error, count } = await query
  if (error) {
    logger.error({ err: error, studioId: authUser.studioId }, 'failed to list commission records')
    return Response.json({ error: 'Failed to fetch records' }, { status: 500 })
  }

  return Response.json({
    data,
    meta: {
      total: count ?? 0,
      page,
      per_page,
      total_pages: Math.ceil((count ?? 0) / per_page),
    },
  })
}

import type { NextRequest } from 'next/server'
import { z } from 'zod'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { requireFeature, hasFeature } from '@/lib/billing/feature-gate'
import { logger } from '@/lib/logger'

const BulkApproveSchema = z.object({
  record_ids: z.array(z.string().uuid()).min(1).max(200),
})

export async function POST(request: NextRequest) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return Response.json({ error: 'Unauthorized' }, { status: 401 })

  const ip = request.headers.get('x-forwarded-for') ?? authUser.user.authId
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return Response.json({ error: 'Too many requests' }, { status: 429 })

  if (!['owner', 'admin'].includes(authUser.role)) {
    return Response.json({ error: 'Forbidden' }, { status: 403 })
  }

  const supabase = await createClient()
  const subResult = await supabase
    .from('subscriptions')
    .select('plan_tier')
    .eq('studio_id', authUser.studioId)
    .eq('status', 'active')
    .maybeSingle()
  const plan = (subResult.data?.plan_tier ?? 'solo') as Parameters<typeof hasFeature>[0]
  const gateResp = requireFeature(plan, 'commissions')
  if (gateResp) return gateResp

  const body = BulkApproveSchema.safeParse(await request.json())
  if (!body.success)
    return Response.json({ error: body.error.flatten() }, { status: 400 })

  const { data, error } = await supabase.rpc('approve_commissions', {
    p_record_ids: body.data.record_ids,
  })

  if (error) {
    logger.error({ err: error, studioId: authUser.studioId }, 'approve_commissions RPC failed')
    return Response.json({ error: 'Failed to approve commissions' }, { status: 500 })
  }

  return Response.json({ approved_count: data })
}

import type { NextRequest } from 'next/server'
import { z } from 'zod'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { requireFeature, hasFeature } from '@/lib/billing/feature-gate'
import { logger } from '@/lib/logger'

interface RouteParams {
  params: Promise<{ id: string }>
}

const IdSchema = z.string().uuid()

export async function GET(request: NextRequest, { params }: RouteParams) {
  const { id } = await params
  const idParsed = IdSchema.safeParse(id)
  if (!idParsed.success) return Response.json({ error: 'Invalid id' }, { status: 400 })

