    logger.error({ err: error, id }, 'failed to expire commission rule')
    return Response.json({ error: 'Failed to expire rule' }, { status: 500 })
  }

  return Response.json({ ok: true })
}

import type { NextRequest } from 'next/server'
import { z } from 'zod'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
