  if (!['owner', 'admin'].includes(authUser.role)) {
    return Response.json({ error: 'Forbidden' }, { status: 403 })
  }

  const ip = request.headers.get('x-forwarded-for') ?? authUser.user.authId
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return Response.json({ error: 'Too many requests' }, { status: 429 })

  const supabase = await createClient()
  const subResult = await supabase
    .from('subscriptions')
    .select('plan_tier')
    .eq('studio_id', authUser.studioId)
    .eq('status', 'active')
    .maybeSingle()
  const plan = (subResult.data?.plan_tier ?? 'solo') as Parameters<typeof hasFeature>[0]
  const gateResp = requireFeature(plan, 'commissions')
  if (gateResp) return gateResp

  const body = PatchAdjSchema.safeParse(await request.json())
  if (!body.success)
    return Response.json({ error: body.error.flatten() }, { status: 400 })

  const { data, error } = await supabase
    .from('commission_adjustments')
    .update({ status: body.data.status })
    .eq('id', id)
    .eq('studio_id', authUser.studioId)
    .select()
    .single()

  if (error) {
    logger.error({ err: error, id }, 'failed to update adjustment status')
    return Response.json({ error: 'Failed to update adjustment' }, { status: 500 })
  }

  return Response.json({ data })
}

import type { NextRequest } from 'next/server'
import { z } from 'zod'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { requireFeature, hasFeature } from '@/lib/billing/feature-gate'
import { logger } from '@/lib/logger'

const ListDisputesSchema = z.object({
  status: z.enum(['open', 'resolved', 'dismissed']).optional(),
  page: z.coerce.number().int().min(1).default(1),
  per_page: z.coerce.number().int().min(1).max(100).default(50),
})

export async function GET(request: NextRequest) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return Response.json({ error: 'Unauthorized' }, { status: 401 })

  const ip = request.headers.get('x-forwarded-for') ?? authUser.user.authId
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return Response.json({ error: 'Too many requests' }, { status: 429 })

  const supabase = await createClient()
  const subResult = await supabase
    .from('subscriptions')
    .select('plan_tier')
    .eq('studio_id', authUser.studioId)
    .eq('status', 'active')
    .maybeSingle()
  const plan = (subResult.data?.plan_tier ?? 'solo') as Parameters<typeof hasFeature>[0]
  const gateResp = requireFeature(plan, 'commissions')
  if (gateResp) return gateResp

  const raw = Object.fromEntries(request.nextUrl.searchParams)
  const parsed = ListDisputesSchema.safeParse(raw)
  if (!parsed.success)
    return Response.json({ error: parsed.error.flatten() }, { status: 400 })

  const { status, page, per_page } = parsed.data

  let query = supabase
    .from('commission_disputes')
    .select(
      `id, commission_record_id, raised_by, reason, status, resolution_notes,
       resolved_at, resolved_by, created_at, updated_at,
       commission_records!commission_disputes_commission_record_id_fkey(
         id, total_cents, service_price_cents, status, artist_id,
         artists!commission_records_artist_id_fkey(id, display_name, avatar_url),
         services!commission_records_service_id_fkey(id, name),
         bookings!commission_records_booking_id_fkey(
           id, scheduled_at,
           clients!bookings_client_id_fkey(id, first_name, last_name))),
       profiles!commission_disputes_raised_by_fkey(id, full_name, avatar_url)`,
      { count: 'exact' },
    )
    .eq('studio_id', authUser.studioId)
    .order('created_at', { ascending: false })
    .range((page - 1) * per_page, page * per_page - 1)

  if (status) query = query.eq('status', status)

  const { data, error, count } = await query
  if (error) {
    logger.error({ err: error }, 'failed to list disputes')
    return Response.json({ error: 'Failed to fetch disputes' }, { status: 500 })
  }

  return Response.json({
    data,
    meta: { total: count ?? 0, page, per_page, total_pages: Math.ceil((count ?? 0) / per_page) },
  })
}

import type { NextRequest } from 'next/server'
import { z } from 'zod'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { requireFeature, hasFeature } from '@/lib/billing/feature-gate'
import { logger } from '@/lib/logger'

interface RouteParams {
  params: Promise<{ id: string }>
}

const ResolveSchema = z.object({
  resolution_notes: z.string().max(2000).default(''),
  outcome: z.enum(['upheld', 'dismissed']),
})

export async function POST(request: NextRequest, { params }: RouteParams) {
  const { id } = await params
  if (!z.string().uuid().safeParse(id).success)
    return Response.json({ error: 'Invalid id' }, { status: 400 })

  const authUser = await getAuthenticatedUser()
  if (!authUser) return Response.json({ error: 'Unauthorized' }, { status: 401 })

  if (!['owner', 'admin'].includes(authUser.role)) {
    return Response.json({ error: 'Forbidden' }, { status: 403 })
  }

  const ip = request.headers.get('x-forwarded-for') ?? authUser.user.authId
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return Response.json({ error: 'Too many requests' }, { status: 429 })

  const supabase = await createClient()
  const subResult = await supabase
    .from('subscriptions')
    .select('plan_tier')
    .eq('studio_id', authUser.studioId)
    .eq('status', 'active')
    .maybeSingle()
  const plan = (subResult.data?.plan_tier ?? 'solo') as Parameters<typeof hasFeature>[0]
  const gateResp = requireFeature(plan, 'commissions')
  if (gateResp) return gateResp

  const body = ResolveSchema.safeParse(await request.json())
  if (!body.success)
    return Response.json({ error: body.error.flatten() }, { status: 400 })

  const { data, error } = await supabase.rpc('resolve_dispute', {
    p_dispute_id: id,
    p_resolution_notes: body.data.resolution_notes,
    p_outcome: body.data.outcome,
  })

  if (error) {
    logger.error({ err: error, id }, 'resolve_dispute RPC failed')
    return Response.json({ error: error.message ?? 'Failed to resolve dispute' }, { status: 500 })
  }

  // Sprint 11 placeholder: logger.info({ disputeId: id, outcome: body.data.outcome }, 'dispute resolved — email notification deferred to Sprint 11')
  logger.info({ disputeId: id, outcome: body.data.outcome }, 'dispute resolved')

  return Response.json({ ok: data })
}
